<?php
include 'header.php';require_once '../includes/gemini.php';
$total_users=(int)$conn->query("SELECT COUNT(*) c FROM users WHERE role='user'")->fetch_assoc()['c'];$total_orders=(int)$conn->query("SELECT COUNT(*) c FROM orders")->fetch_assoc()['c'];$total_revenue=(float)$conn->query("SELECT COALESCE(SUM(total_money),0) c FROM orders WHERE status='completed'")->fetch_assoc()['c'];$total_products=(int)$conn->query("SELECT COUNT(*) c FROM products")->fetch_assoc()['c'];$pending_orders=(int)$conn->query("SELECT COUNT(*) c FROM orders WHERE status='pending'")->fetch_assoc()['c'];$processing_orders=(int)$conn->query("SELECT COUNT(*) c FROM orders WHERE status='processing'")->fetch_assoc()['c'];$completed_orders=(int)$conn->query("SELECT COUNT(*) c FROM orders WHERE status='completed'")->fetch_assoc()['c'];$canceled_orders=(int)$conn->query("SELECT COUNT(*) c FROM orders WHERE status='canceled'")->fetch_assoc()['c'];
// Tồn kho hiệu lực: sản phẩm có biến thể đang bán -> tổng tồn kho các biến thể; không có biến thể -> tồn kho gốc của sản phẩm.
$stock_rows=[];$sqStock=$conn->query("SELECT p.id,p.name,p.sales_count,p.stock_quantity,COUNT(v.id) variant_count,COALESCE(SUM(v.stock_quantity),0) variant_stock FROM products p LEFT JOIN product_variants v ON v.product_id=p.id AND v.status=1 GROUP BY p.id,p.name,p.sales_count,p.stock_quantity");
while($r=$sqStock->fetch_assoc()){$effective=(int)$r['variant_count']>0?(int)$r['variant_stock']:(int)$r['stock_quantity'];$stock_rows[]=['name'=>$r['name'],'sales_count'=>(int)$r['sales_count'],'stock'=>$effective];}
$low_stock=count(array_filter($stock_rows,function($r){return $r['stock']<=10;}));
$out_stock=count(array_filter($stock_rows,function($r){return $r['stock']<=0;}));
$orders_query=$conn->query("SELECT o.*,u.fullname FROM orders o JOIN users u ON o.user_id=u.id ORDER BY o.created_at DESC LIMIT 6");
$month_labels=[];$monthly_revenue=[];$monthly_orders=[];for($i=5;$i>=0;$i--){$ts=strtotime("-$i months");$key=date('Y-m',$ts);$month_labels[]=date('m/Y',$ts);$safe=$conn->real_escape_string($key);$q=$conn->query("SELECT COALESCE(SUM(CASE WHEN status='completed' THEN total_money ELSE 0 END),0) revenue,COUNT(*) order_count FROM orders WHERE DATE_FORMAT(created_at,'%Y-%m')='$safe'")->fetch_assoc();$monthly_revenue[]=(float)$q['revenue'];$monthly_orders[]=(int)$q['order_count'];}
usort($stock_rows,function($a,$b){return $a['stock']<=>$b['stock']?:$b['sales_count']<=>$a['sales_count'];});
$stock_labels=[];$stock_values=[];foreach(array_slice($stock_rows,0,7) as $r){$stock_labels[]=$r['name'];$stock_values[]=$r['stock'];}
$category_labels=[];$category_values=[];$cq=$conn->query("SELECT c.name,COUNT(p.id) total FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id,c.name ORDER BY total DESC");while($r=$cq->fetch_assoc()){$category_labels[]=$r['name'];$category_values[]=(int)$r['total'];}$models=gemini_model_options();$dashboard_model=gemini_get_setting($conn,'gemini_dashboard_model','gemini-3.5-flash');
?>
<style>
