round:#edf6f0;color:#55755e}.canceled{background:#fff0ef;color:#a75450}@media(max-width:1100px){.dashboard-board{grid-template-columns:1fr}.kpi-stack{grid-template-columns:repeat(4,1fr)}}@media(max-width:850px){.visual-board,.lower-grid{grid-template-columns:1fr}.side-charts{grid-template-columns:1fr 1fr;grid-template-rows:none}.kpi-stack{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.dashboard-head{flex-direction:column;align-items:flex-start}.dashboard-actions{display:none}.kpi-stack,.side-charts{grid-template-columns:1fr}.ai-head{align-items:flex-start;flex-direction:column}.ai-controls{width:100%}.ai-controls select{flex:1;max-width:none}}
