<div class="dashboard-head"><div><small>TRUNG TÂM QUẢN TRỊ</small><h1>Tổng quan cửa hàng công nghệ</h1><p>Theo dõi doanh thu, đơn hàng, tồn kho và phân tích Gemini AI trong bố cục trực quan mới.</p></div><div class="dashboard-actions"><a href="products.php"><i class="fas fa-plus"></i> Thêm sản phẩm</a><a href="orders.php"><i class="fas fa-box"></i> Xử lý đơn</a></div></div><section class="dashboard-board"><div class="kpi-stack"><div class="kpi-card"><div class="kpi-icon"><i class="fas fa-coins"></i></div><div><span>Doanh thu hoàn thành</span><strong><?php echo number_format($total_revenue,0,',','.'); ?> đ</strong><small><?php echo $total_orders; ?> đơn toàn hệ thống</small></div></div><div class="kpi-card"><div class="kpi-icon"><i class="fas fa-box"></i></div><div><span>Đơn cần xử lý</span><strong><?php echo $pending_orders+$processing_orders; ?></strong><small><?php echo $pending_orders; ?> chờ, <?php echo $processing_orders; ?> đang giao</small></div></div><div class="kpi-card"><div class="kpi-icon"><i class="fas fa-microchip"></i></div><div><span>Tồn kho cần chú ý</span><strong><?php echo $low_stock; ?></strong><small><?php echo $out_stock; ?> sản phẩm hết hàng</small></div></div><div class="kpi-card"><div class="kpi-icon"><i class="fas fa-users"></i></div><div><span>Khách hàng</span><strong><?php echo $total_users; ?></strong><small><?php echo $total_products; ?> sản phẩm đang quản lý</small></div></div></div><div class="visual-board"><div class="panel"><div class="panel-head"><h2><i class="fas fa-chart-line"></i> Nhịp doanh thu 6 tháng</h2><span>Doanh thu và số đơn</span></div><div class="chart-wrap"><canvas id="revenueChart"></canvas></div></div><div class="side-charts"><div class="panel"><div class="panel-head"><h2><i class="fas fa-chart-pie"></i> Trạng thái đơn</h2></div><div class="chart-wrap"><canvas id="statusChart"></canvas></div></div><div class="panel"><div class="panel-head"><h2><i class="fas fa-layer-group"></i> Cơ cấu danh mục</h2></div><div class="chart-wrap"><canvas id="categoryChart"></canvas></div></div></div></div></section><section class="lower-grid"><div class="panel"><div class="panel-head"><h2><i class="fas fa-boxes-stacked"></i> Tồn kho thấp</h2><span>7 sản phẩm cần chú ý</span></div><div class="chart-wrap"><canvas id="stockChart"></canvas></div></div><aside class="ai-panel"><div class="ai-head"><h2><i class="fas fa-wand-magic-sparkles"></i> Gemini AI phân tích</h2><div class="ai-controls"><select id="dashboardAiModel"><?php foreach($models as $modelId=>$modelName):?><option value="<?php echo htmlspecialchars($modelId); ?>" <?php echo $modelId===$dashboard_model?'selected':''; ?>><?php echo htmlspecialchars($modelName); ?></option><?php endforeach;?><?php foreach(gemini_legacy_models() as $modelId=>$modelName):?><option value="<?php echo htmlspecialchars($modelId); ?>" disabled><?php echo htmlspecialchars($modelName); ?> — đã ngừng API</option><?php endforeach;?></select><button type="button" id="runAiAnalysis"><i class="fas fa-bolt"></i> Phân tích</button></div></div><div class="ai-body" id="aiAnalysisBody"><div class="ai-placeholder"><div><i class="fas fa-robot" style="font-size:29px;color:var(--primary);margin-bottom:8px"></i><br>Nhấn “Phân tích” để AI đọc dữ liệu doanh thu, đơn hàng và tồn kho.</div></div></div></aside></section><section class="orders-panel"><div class="panel-head"><h2><i class="fas fa-receipt"></i> Đơn hàng gần đây</h2><a href="orders.php">Xem tất cả</a></div><div class="table-wrap"><table class="order-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Tổng tiền</th><th>Ngày đặt</th><th>Trạng thái</th></tr></thead><tbody><?php while($o=$orders_query->fetch_assoc()):$labels=['pending'=>'Chờ xử lý','processing'=>'Đang giao','completed'=>'Hoàn thành','canceled'=>'Đã hủy'];?><tr><td><span class="order-id"><?php echo $o['id']; ?></span></td><td><?php echo htmlspecialchars($o['fullname']); ?></td><td><span class="money"><?php echo number_format($o['total_money'],0,',','.'); ?> đ</span></td><td><?php echo date('d/m/Y H:i',strtotime($o['created_at'])); ?></td><td><span class="status-badge <?php echo htmlspecialchars($o['status']); ?>"><?php echo $labels[$o['status']]??$o['status']; ?></span></td></tr><?php endwhile;?></tbody></table></div></section>
<script>document.addEventListener('DOMContentLoaded',function(){const font='Times New Roman',colors=['#2563eb','#c49a6c','#6f8d79','#8798b5','#b96f62','#9276a5','#c1a15c','#6f8f91'];new Chart(document.getElementById('revenueChart'),{data:{labels:<?php echo json_encode($month_labels,JSON_UNESCAPED_UNICODE); ?>,datasets:[{type:'bar',label:'Doanh thu',data:<?php echo json_encode($monthly_revenue); ?>,backgroundColor:colors.slice(0,6),borderRadius:7,yAxisID:'y'},{type:'line',label:'Số đơn',data:<?php echo json_encode($monthly_orders); ?>,borderColor:'#5d7f6a',backgroundColor:'#5d7f6a',tension:.35,pointRadius:4,pointBackgroundColor:colors.slice(0,6),yAxisID:'y1'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{font:{family:font,size:11}}}},scales:{x:{grid:{display:false},ticks:{font:{family:font,size:10}}},y:{beginAtZero:true,grid:{color:'#eee8e2'},ticks:{font:{family:font,size:10},callback:function(v){return new Intl.NumberFormat('vi-VN',{notation:'compact'}).format(v)+' đ'}}},y1:{beginAtZero:true,position:'right',grid:{display:false},ticks:{precision:0,font:{family:font,size:10}}}}}});new Chart(document.getElementById('statusChart'),{type:'doughnut',data:{labels:['Chờ xử lý','Đang giao','Hoàn thành','Đã hủy'],datasets:[{data:[<?php echo $pending_orders; ?>,<?php echo $processing_orders; ?>,<?php echo $completed_orders; ?>,<?php echo $canceled_orders; ?>],backgroundColor:['#c1a15c','#8798b5','#6f8d79','#b96f62'],borderWidth:2,borderColor:'#fff'}]},options:{responsive:true,maintainAspectRatio:false,cutout:'62%',plugins:{legend:{position:'right',labels:{boxWidth:9,font:{family:font,size:9}}}}}});new Chart(document.getElementById('categoryChart'),{type:'pie',data:{labels:<?php echo json_encode($category_labels,JSON_UNESCAPED_UNICODE); ?>,datasets:[{data:<?php echo json_encode($category_values); ?>,backgroundColor:colors,borderWidth:2,borderColor:'#fff'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'right',labels:{boxWidth:8,font:{family:font,size:8}}}}}});new Chart(document.getElementById('stockChart'),{type:'bar',data:{labels:<?php echo json_encode($stock_labels,JSON_UNESCAPED_UNICODE); ?>,datasets:[{label:'Tồn kho',data:<?php echo json_encode($stock_values); ?>,backgroundColor:colors.slice(1,8),borderRadius:6}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,grid:{color:'#eee8e2'},ticks:{precision:0,font:{family:font,size:10}}},y:{grid:{display:false},ticks:{font:{family:font,size:10},callback:function(v){const label=this.getLabelForValue(v);return label.length>24?label.slice(0,24)+'…':label}}}}}});const button=document.getElementById('runAiAnalysis'),body=document.getElementById('aiAnalysisBody'),model=document.getElementById('dashboardAiModel');button.addEventListener('click',async function(){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin"></i> Đang phân tích';body.innerHTML='<div class="ai-placeholder"><div><i class="fas fa-spinner fa-spin" style="font-size:26px;color:var(--primary);margin-bottom:8px"></i><br>Gemini đang đọc dữ liệu hệ thống...</div></div>';try{const response=await fetch('ai_analysis.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:model.value})});const data=await response.json();if(!response.ok||data.status!=='success')throw new Error(data.message||'Không thể phân tích dữ liệu');const a=data.analysis||{},conclusions=Array.isArray(a.conclusions)?a.conclusions:[],actions=Array.isArray(a.actions)?a.actions:[],warnings=Array.isArray(a.warnings)?a.warnings:[];body.innerHTML='<div class="ai-summary"></div><div class="ai-columns"><div class="ai-block"><h3>Kết luận</h3><div class="ai-list js-conclusions"></div></div><div class="ai-block"><h3>Việc nên làm</h3><div class="ai-list js-actions"></div></div></div><div class="ai-block" style="margin-top:7px"><h3>Cảnh báo</h3><div class="ai-list js-warnings"></div></div>';body.querySelector('.ai-summary').textContent=a.summary||'AI đã hoàn tất phân tích.';const c=body.querySelector('.js-conclusions');conclusions.forEach(function(x){const d=document.createElement('div');d.textContent='• '+x;c.appendChild(d)});const ac=body.querySelector('.js-actions');actions.forEach(function(x){const d=document.createElement('div');d.textContent='• '+x;ac.appendChild(d)});const w=body.querySelector('.js-warnings');if(!warnings.length){const d=document.createElement('div');d.textContent='Chưa phát hiện cảnh báo đáng chú ý.';w.appendChild(d)}warnings.forEach(function(x){const d=document.createElement('div');d.className='warning-item';d.textContent=(x.title||'Cảnh báo')+': '+(x.detail||'');w.appendChild(d)})}catch(error){body.innerHTML='<div class="ai-placeholder">'+(error.message||'Không thể kết nối Gemini AI.')+'</div>'}finally{button.disabled=false;button.innerHTML='<i class="fas fa-bolt"></i> Phân tích'}})})</script><?php include 'footer.php'; ?>